class FoodRatings {
    unordered_map<string, pair<string, int>> foodInfo;
    unordered_map<string, set<pair<int, string>>> cuisineSet;
public:
    FoodRatings(vector<string>& foods, vector<string>& cuisines, vector<int>& ratings) {
        int n = foods.size();
        for (int i = 0; i < n; i++) {
            foodInfo[foods[i]] = {cuisines[i], ratings[i]};
            cuisineSet[cuisines[i]].insert({-ratings[i], foods[i]});
        }
    }

    void changeRating(string food, int newRating) {
        auto& info = foodInfo[food];
        string cuisine = info.first;
        int oldRating = info.second;
        cuisineSet[cuisine].erase({-oldRating, food});
        cuisineSet[cuisine].insert({-newRating, food});
        info.second = newRating;
    }

    string highestRated(string cuisine) {
        return cuisineSet[cuisine].begin()->second;
    }
};
